import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the committed solver-parity golden-vector corpus through
/// `WeightedSquaredErrorScorer` and `CompositionSolver`.
///
/// The corpus is generated by the `color_matching` server
/// (`priv/parity/v1/corpus.json`, `mix parity.generate`; viamin/color_matching#112)
/// and committed here as a test fixture. Every scenario records the palette
/// response vectors, the target vector, the channel weights, the per-candidate
/// score table (`"excluded"` marks missing-measurement exclusions), the expected
/// selection and error, and explicit tie-break evidence. Any mismatch means the
/// client has diverged from the server on tie-breaking, missing-measurement
/// exclusion, or channel weighting.
///
/// The corpus is stamped with an `algorithm_version`; when it changes, every
/// expectation has moved and this test (and the fixture) must be updated in step.
///
/// Refresh the fixture with:
/// `curl -o Fixtures/parity/v1/corpus.json https://raw.githubusercontent.com/viamin/color_matching/master/priv/parity/v1/corpus.json`
/// (see docs/parity-corpus.md).
final class SolverParityCorpusTests: XCTestCase {
    private static let corpusURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures/parity/v1/corpus.json")

    private static let supportedAlgorithmVersion = 1

    // MARK: - Corpus decoding (test-only mirror of the fixture format)

    private struct ParityCorpus: Decodable {
        let algorithmVersion: Int
        let scorer: String
        let selection: String
        let missingPolicy: String
        let lightSources: [String]
        let scenarios: [ParityScenario]

        enum CodingKeys: String, CodingKey {
            case algorithmVersion = "algorithm_version"
            case scorer
            case selection
            case missingPolicy = "missing_policy"
            case lightSources = "light_sources"
            case scenarios
        }
    }

    private struct ParityScenario: Decodable {
        let id: String
        let description: String
        let weights: [String: Double]
        let target: ParityVector
        let palette: [ParityVector]
        let expected: ParityExpected
    }

    private struct ParityVector: Decodable {
        let index: Int?
        let hexColor: String
        let channels: [String: Double]

        enum CodingKeys: String, CodingKey {
            case index
            case hexColor = "hex_color"
            case channels
        }
    }

    private struct ParityExpected: Decodable {
        let scores: [ParityScoreEntry]
        let selectedIndex: Int?
        let selectedHexColor: String?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]

        enum CodingKeys: String, CodingKey {
            case scores
            case selectedIndex = "selected_index"
            case selectedHexColor = "selected_hex_color"
            case error
            case tieBroke = "tie_broke"
            case tiedIndices = "tied_indices"
        }
    }

    private struct ParityScoreEntry: Decodable {
        let index: Int
        let score: ParityScore
    }

    /// A recorded per-candidate score: a finite double, or the string
    /// `"excluded"` when the missing-measurement policy ruled the candidate out.
    private enum ParityScore: Decodable, Equatable {
        case value(Double)
        case excluded

        init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let marker = try? container.decode(String.self), marker == "excluded" {
                self = .excluded
            } else {
                self = .value(try container.decode(Double.self))
            }
        }

        static func == (lhs: ParityScore, rhs: ParityScore) -> Bool {
            switch (lhs, rhs) {
            case (.excluded, .excluded): return true
            case (.value(let a), .value(let b)): return a == b
            default: return false
            }
        }
    }

    // MARK: - Loading

    private func loadCorpus(file: StaticString = #filePath, line: UInt = #line) throws -> ParityCorpus {
        let data: Data
        do {
            data = try Data(contentsOf: Self.corpusURL)
        } catch {
            XCTFail("parity corpus fixture is missing or unreadable at \(Self.corpusURL.path): \(error)", file: file, line: line)
            throw error
        }
        return try JSONDecoder().decode(ParityCorpus.self, from: data)
    }

    // MARK: - Corpus-level invariants

    /// The corpus semantics this replay understands. A different
    /// `algorithm_version` means every recorded expectation moved; update the
    /// fixture and this test together.
    func testCorpusMetadataMatchesSupportedAlgorithmVersion() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, Self.supportedAlgorithmVersion)
        XCTAssertTrue(corpus.scorer.contains("WeightedSquaredError"), "corpus scorer changed: \(corpus.scorer)")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
        XCTAssertFalse(corpus.scenarios.isEmpty)
    }

    func testCorpusIsWellFormed() throws {
        let corpus = try loadCorpus()

        let ids = corpus.scenarios.map(\.id)
        XCTAssertEqual(Set(ids).count, ids.count, "scenario ids must be unique")
        XCTAssertTrue(ids.allSatisfy { !$0.isEmpty })

        for scenario in corpus.scenarios {
            XCTAssertEqual(
                scenario.palette.map(\.index),
                scenario.palette.indices.map { Optional($0) },
                "scenario \(scenario.id): palette indices must be 0..<count in order"
            )
            XCTAssertEqual(
                scenario.expected.scores.map(\.index),
                Array(scenario.palette.indices),
                "scenario \(scenario.id): score table must cover every palette index in order"
            )
        }
    }

    /// The corpus must keep covering the semantics that historically drift
    /// between client and server: exact ties, missing-measurement exclusions,
    /// and scenarios where no candidate is selectable at all.
    func testCorpusCoversTiesExclusionsAndNoSelectionCases() throws {
        let corpus = try loadCorpus()

        XCTAssertGreaterThanOrEqual(corpus.scenarios.filter { $0.expected.tieBroke == true }.count, 1,
                                    "corpus must include at least one tie-broken scenario")
        XCTAssertGreaterThanOrEqual(
            corpus.scenarios.filter { scenario in scenario.expected.scores.contains { $0.score == .excluded } }.count,
            1,
            "corpus must include at least one excluded candidate"
        )
        XCTAssertGreaterThanOrEqual(corpus.scenarios.filter { $0.expected.selectedIndex == nil }.count, 1,
                                    "corpus must include at least one no-selection scenario")
    }

    // MARK: - Scorer parity (score table)

    /// Every recorded score must match `WeightedSquaredErrorScorer` exactly —
    /// no tolerance. Corpus values are exact dyadic rationals, so any mismatch
    /// is a real divergence in weighting, exclusion, or arithmetic.
    func testScorerScoreTableMatchesCorpusExactly() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for scenario in corpus.scenarios {
            let weights = Self.weights(from: scenario.weights)
            let target = Self.target(from: scenario.target)
            let palette = try Self.palette(from: scenario)

            for entry in scenario.expected.scores {
                let candidate = palette[entry.index]
                let result = scorer.score(candidate: candidate, target: target, weights: weights)

                switch (result, entry.score) {
                case (.score(let value), .value(let expected)):
                    // Exact equality: corpus values are exact dyadic rationals,
                    // so even a last-bit divergence is a real parity failure.
                    XCTAssertEqual(value, expected,
                                   "scenario \(scenario.id): candidate \(entry.index) score mismatch")
                case (.excluded, .excluded):
                    break
                default:
                    XCTFail("scenario \(scenario.id): candidate \(entry.index) got \(result), corpus says \(entry.score)")
                }
            }
        }
    }

    // MARK: - Selection parity (earliest-wins replay)

    /// Replaying the recorded score table with the server's documented
    /// earliest-index-wins rule must reproduce the recorded selection, error,
    /// tie flag, and tied index set for every scenario.
    func testEarliestWinsSelectionMatchesCorpus() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let selection = try Self.replaySelection(for: scenario)
            let expected = scenario.expected
            let label = "scenario \(scenario.id)"

            XCTAssertEqual(selection.selectedIndex, expected.selectedIndex, label)
            XCTAssertEqual(selection.tiedIndices, expected.tiedIndices, label)

            if let selectedIndex = expected.selectedIndex {
                let expectedError = try XCTUnwrap(expected.error, "\(label): selected scenario must record an error")
                XCTAssertEqual(selection.error, expectedError, label)
                XCTAssertEqual(selection.tieBroke, expected.tieBroke, label)
                XCTAssertEqual(scenario.palette[selectedIndex].hexColor,
                               try XCTUnwrap(expected.selectedHexColor, label), label)
            } else {
                XCTAssertNil(selection.error, label)
                XCTAssertNil(selection.tieBroke, label)
            }
        }
    }

    /// The corpus's `selection` field describes the whole app: the solver's
    /// per-cell choice. Replaying each scenario as a 1×1 composition through
    /// `CompositionSolver` (its optimized fast path) must select the recorded
    /// palette index with the recorded error, exercising the solver's own
    /// earliest-wins tie-breaking rather than a test-side reimplementation.
    func testSolverFastPathSelectionMatchesCorpus() throws {
        let corpus = try loadCorpus()
        var replayedScenarios = 0

        for scenario in corpus.scenarios {
            let weights = Self.weights(from: scenario.weights)
            let active = weights.activeConditions

            // A scenario whose target is itself missing an active channel has
            // no source grid to build; the scorer-level replay above covers it.
            guard active.allSatisfy({ scenario.target.channels[$0.rawValue] != nil }) else { continue }
            replayedScenarios += 1

            let palette = try Self.palette(from: scenario)
            var grids: [LightingCondition: BrightnessGrid] = [:]
            for condition in active {
                let brightness = try XCTUnwrap(scenario.target.channels[condition.rawValue],
                                               "scenario \(scenario.id): target channel \(condition.rawValue)")
                grids[condition] = BrightnessGrid(width: 1, height: 1, values: [brightness])
            }

            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: grids,
                weights: weights
            )

            let label = "scenario \(scenario.id)"
            XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, label)

            if scenario.expected.selectedIndex != nil {
                let expectedError = try XCTUnwrap(scenario.expected.error, label)
                XCTAssertEqual(result.error(x: 0, y: 0), expectedError, label)
            } else {
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, label)
                XCTAssertEqual(result.unmatchedCellCount, 1, label)
            }
        }

        XCTAssertGreaterThanOrEqual(replayedScenarios, 1,
                                    "corpus must offer at least one solver-replayable scenario")
    }

    // MARK: - Corpus → domain adapters

    /// Builds `ChannelWeights` from the recorded weights map. Unknown light
    /// sources (e.g. `ultraviolet`) are ignored, and unlisted conditions count
    /// as weight zero — matching how the app's weight UI maps onto channels.
    private static func weights(from recorded: [String: Double]) -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double { recorded[condition.rawValue] ?? 0 }
        return ChannelWeights(
            white: weight(.white),
            red: weight(.red),
            green: weight(.green),
            blue: weight(.blue),
            lps: weight(.lps)
        )
    }

    private static func target(from entry: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in entry.channels {
            if let condition = LightingCondition(rawValue: key) { brightness[condition] = value }
        }
        return TargetResponseVector(brightness)
    }

    private static func palette(from scenario: ParityScenario) throws -> [PaletteColor] {
        try scenario.palette.map { entry in
            let rgb = try XCTUnwrap(RGBColor(hex: entry.hexColor),
                                    "scenario \(scenario.id): unparseable corpus hex \(entry.hexColor)")
            var responses: [LightingCondition: IlluminationResponse] = [:]
            for (key, value) in entry.channels {
                if let condition = LightingCondition(rawValue: key) {
                    responses[condition] = IlluminationResponse(brightness: value)
                }
            }
            return PaletteColor(id: entry.index ?? -1, hex: entry.hexColor, rgb: rgb, responses: responses)
        }
    }

    private struct ReplaySelection {
        let selectedIndex: Int?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]
    }

    /// Scores every palette candidate with `WeightedSquaredErrorScorer` and
    /// applies the server's selection rule: the earliest candidate achieving
    /// the strict minimum score wins.
    private static func replaySelection(for scenario: ParityScenario) throws -> ReplaySelection {
        let scorer = WeightedSquaredErrorScorer()
        let weights = weights(from: scenario.weights)
        let targetVector = target(from: scenario.target)
        let palette = try palette(from: scenario)

        var results: [ScorerResult] = []
        for candidate in palette {
            results.append(scorer.score(candidate: candidate, target: targetVector, weights: weights))
        }

        var best: (index: Int, score: Double)?
        for (index, result) in results.enumerated() {
            guard case .score(let value) = result else { continue }
            if let current = best {
                if value < current.score { best = (index, value) }
            } else {
                best = (index, value)
            }
        }

        guard let best else {
            return ReplaySelection(selectedIndex: nil, error: nil, tieBroke: nil, tiedIndices: [])
        }

        let tied = results.indices.compactMap { index -> Int? in
            guard case .score(let value) = results[index], value == best.score else { return nil }
            return index
        }

        return ReplaySelection(
            selectedIndex: best.index,
            error: best.score,
            tieBroke: tied.count > 1,
            tiedIndices: tied
        )
    }
}
